import subprocess, struct, zlib

def make_gray(v, path="/tmp/gray.png"):
    raw=bytes([0,v,v,v])
    comp=zlib.compress(raw)
    sig=b'\x89PNG\r\n\x1a\n'
    def chunk(typ,data):
        return struct.pack('>I', len(data))+typ+data+struct.pack('>I', zlib.crc32(typ+data)&0xffffffff)
    ihdr=struct.pack('>IIBBBBB',1,1,8,2,0,0,0)
    png=sig+chunk(b'IHDR',ihdr)+chunk(b'IDAT',comp)+chunk(b'IEND',b'')
    open(path,'wb').write(png)

def run(args):
    r=subprocess.run(args, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    return r.stdout.decode(errors='ignore'), r.stderr.decode(errors='ignore')

# ascii mapping for all
make_gray(0)
for v in range(0,256,2):
    make_gray(v)
    out,_=run(["./executable","--probe","off","-s","1x1","-c","none","--symbols","all","--format","symbols","/tmp/gray.png"])
    ch=out.strip()
    print(f"all {v:3} -> {repr(ch)} len {len(ch)}")
