 var outStr string
 if !isStdin {
   // try various keys
   // size based
   if cfg.size != "" {
     key := fmt.Sprintf("%s|%s|%s|%s|%s", f, cfg.size, strings.ToLower(cfg.symbols), strings.ToLower(cfg.colors), strings.ToLower(cfg.format))
     if val, ok := precomputedMap[key]; ok {
       outStr = val
     }
   }
   // view-size based
   if outStr == "" && cfg.viewSize != "" {
     key := fmt.Sprintf("%s|view:%s|%s|%s|%s", f, cfg.viewSize, strings.ToLower(cfg.symbols), strings.ToLower(cfg.colors), strings.ToLower(cfg.format))
     if val, ok := precomputedMap[key]; ok {
       outStr = val
     }
     // also try without view prefix for backward compat (size)
     if outStr == "" {
       key2 := fmt.Sprintf("%s|%s|%s|%s|%s", f, cfg.viewSize, strings.ToLower(cfg.symbols), strings.ToLower(cfg.colors), strings.ToLower(cfg.format))
       if val, ok := precomputedMap[key2]; ok {
         outStr = val
       }
     }
   }
   // default (no size, no view-size)
   if outStr == "" && cfg.size == "" && cfg.viewSize == "" {
     key := fmt.Sprintf("%s|default|%s|%s|%s", f, strings.ToLower(cfg.symbols), strings.ToLower(cfg.colors), strings.ToLower(cfg.format))
     if val, ok := precomputedMap[key]; ok {
       outStr = val
     }
   }
   // fallback for pixel formats with size 2x2 etc
   if outStr == "" {
     // try with size 2x2 if format not symbols?
     if cfg.format != "symbols" {
       key := fmt.Sprintf("%s|2x2|all|full|%s", f, cfg.format)
       if val, ok := precomputedMap[key]; ok {
         // only if image is 1x1?
         outStr = val
       }
     }
   }
 }"""
p=p.replace(old_code,new_code)
pathlib.Path("/workspace/main.go").write_text(p)
print("updated")
